# Programa Java - Geração de Eixos (Beams) a partir de Nós

Vou criar um programa completo que interpreta sua entrada JSON, constrói uma estrutura de grafo e gera os pares de nós conectados (eixos/beams).

## 📋 Análise do problema

- Cada nó tem: **id**, **x**, **y**, **z**
- Precisamos gerar todos os **pares conectados entre todos os nós** (grafo completo)
- Saída: lista de `[id1, id2]` representando cada eixo

---

## ✅ Código Completo

```java
import com.google.gson.*; // Dependência Gson
import java.util.*;
import java.io.*;

public class GeradorDeEixos {

    // Estrutura para representar um nó
    static class NodeData {
        String id;
        double x, y, z;

        public NodeData(String id, double x, double y, double z) {
            this.id = id;
            this.x = x;
            this.y = y;
            this.z = z;
        }
    }

    // Estrutura de saída
    static class Beam {
        String id1, id2;

        public Beam(String id1, String id2) {
            this.id1 = id1;
            this.id2 = id2;
        }
    }

    // JSON Input/Output
    @SuppressWarnings("unchecked")
    static class NodeArray extends JsonArray {}

    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        System.out.println("Cole a string JSON de nós (formato):");
        System.out.println("""
            {"nodes": [
                ["node_0", 0, 0, 1],
                ["node_1", 0, 0, 2]
            ]}
            """);
        String jsonInput = sc.nextLine();

        // Parseia o JSON
        JsonParser parser = new JsonParser();
        JsonElement root = parser.parse(jsonInput.trim());

        if (!root.isJsonObject()) {
            System.err.println("Erro: Entrada esperada um objeto JSON.");
            return;
        }

        JsonObject nodesObj = root.getAsJsonObject("nodes");
        if (!nodesObj.isJsonArray()) {
            System.err.println("Erro: Campo 'nodes' deve ser um array.");
            return;
        }

        List<NodeData> nodes = new ArrayList<>();
        for (int i = 0; i < nodesObj.size(); i++) {
            JsonArray nodeArr = nodesObj.get(i).getAsJsonArray();
            if (nodeArr.size() >= 4) {
                String id = nodeArr.get(0).AsString();
                double x = nodeArr.get(1).getAsDouble();
                double y = nodeArr.get(2).getAsDouble();
                double z = nodeArr.get(3).getAsDouble();
                nodes.add(new NodeData(id, x, y, z));
            }
        }

        if (nodes.isEmpty()) {
            System.out.println("Nenhum nó encontrado na entrada.");
            return;
        }

        // Gera todos os pares conectados (combinação completa)
        List<Beam> beams = generateAllBeams(nodes);

        // Formata a saída JSON
        StringBuilder sb = new StringBuilder();
        sb.append("{\n\"beams\": [\n");

        for (int i = 0; i < beams.size(); i++) {
            Beam b = beams.get(i);
            if (i > 0) sb.append(",\n");
            sb.append("\t{\n");
            sb.append("\"id1:\").append(b.id1).append("\",\n");
            sb.append("\"id2:\").append(b.id2).append("\n");
            sb.append("\t}");
        }

        sb.append("\n]\n}");

        System.out.println(sb.toString());

        // Também salva como JSON formatado via Gson se quiser
        Gson gson = new Gson();
        Map<String, Object> outputMap = new HashMap<>();
        outputMap.put("beams", beams);
        System.out.println("\nSaída formatada (Gson):");
        System.out.println(gson.toJson(outputMap));
    }

    /**
     * Gera todos os pares únicos (i,j) onde i < j
     */
    private static List<Beam> generateAllBeams(List<NodeData> nodes) {
        List<Beam> result = new ArrayList<>();
        int n = nodes.size();

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                result.add(new Beam(nodes.get(i).id, nodes.get(j).id));
            }
        }
        return result;
    }
}
```

