## ✅ Versão 4 — Detecção de Drift Acumulado

Detecta quando o erro se acumula ao longo do tempo (descompasso progressivo).

```javascript
adjustSynchronization(currentTime) {
    if (!this.cumulativeDrift) this.cumulativeDrift = 0;

    if (this.speechQueue.length > 0) {
        const nextSpeechTime = this.speechQueue[0].startTime;
        const currentTimeClipped = Math.max(0, currentTime - this.lastProcessedTime || 0);
        const immediateDiff = nextSpeechTime - currentTimeClipped;
        this.cumulativeDrift += (immediateDiff - 1000); // desvio médio esperado

        // Reset se ultrapassar muito (nova fala/seção)
        if (Math.abs(this.cumulativeDrift) > 3000) this.cumulativeDrift = 0;

        if (this.dubbingMode === 'advanced' && this.cumulativeDrift > 600) {
            // Degradação acumulada: acelera mais agressivamente
            const maxSpeed = parseFloat(this.maxSpeedControl.value);
            this.speedControl.value = Math.min(
                this.speedControl.value + 0.07,
                maxSpeed
            );
        } else if (this.cumulativeDrift < -800) {
            // Adiantou demais: freia
            this.speedControl.value = Math.max(1.0, this.speedControl.value - 0.1);
            if (this.speakingControlMode === 'slowDown') {
                this.video.playbackRate = Math.max(this.video.playbackRate - 0.1, 1.0);
            }
        } else {
            this.speedControl.value = this.userConfiguredSpeed;
            if (this.speakingControlMode === 'slowDown') this.video.playbackRate = 1.0;
        }
        this.updateRangeValue('speed');
    }

    this.lastProcessedTime = currentTime;
}
