        const nextSpeechTime = this.speechQueue[0].startTime;
        const diff = nextSpeechTime - currentTime;
        const maxSpeed = parseFloat(this.maxSpeedControl.value);

        if (diff < 500) {
            this.speedControl.value = Math.min(maxSpeed, this.speedControl.value + 0.06);
        } else if (diff > 1000) {
            this.speedControl.value = 1.2;
            if (this.speakingControlMode === 'slowDown') {
                this.video.playbackRate = Math.max(this.video.playbackRate - 0.1, 1.0);
            }
        } else {
            this.speedControl.value = this.userConfiguredSpeed;
            if (this.speakingControlMode === 'slowDown') this.video.playbackRate = 1.0;
        }
    } else {
        // Fallback manual: respeita configurações do usuário
        if (this.speedControl.value !== this.userConfiguredSpeed) {
            // Transição suave de volta ao manual
            const t = Math.min((currentTime - this.manualLastAdjust) / 500, 1);
            this.speedControl.value = this.userConfiguredSpeed + (1 - this.speedControl.value) * t;
            this.video.playbackRate = 1.0;
        }
        this.manualLastAdjust = currentTime;
    }
    this.updateRangeValue('speed');
}
