## ✅ Versão 7 — Logging + Métricas de Saúde da Sincronização

Adiciona telemetria interna para debugging e monitoramento em tempo real.

```javascript
class SyncMetrics {
    constructor() {
        this.events = [];
        this.consecutiveCorrect = 0;
        this.maxConsecutiveCorrect = 0;
    }
    record(event) { this.events.push(event); this.events.splice(0, this.events.length - 50); }
    getHealthSummary() {
        if (this.events.length === 0) return { status: 'idle', accuracy: 0 };
        const recent = this.events.slice(-50);
        let correct = 0;
        for (const e of recent) {
            if (Math.abs(e.diff - 1000) < 300) correct++;
        }
        return {
            status: correct / (recent.length || 1) > 0.8 ? 'healthy' : 'warning',
            accuracy: Math.round((correct / (recent.length || 1)) * 100),
            lastEvent: recent[recent.length - 1]
        };
    }
}

const metrics = new SyncMetrics();

adjustSynchronization(currentTime) {
    if (this.speechQueue.length > 0) {
        const nextSpeechTime = this.speechQueue[0].startTime;
        const diff = nextSpeechTime - currentTime;
        const mode = this.dubbingMode ?? 'basic';

        let target = 1.0;
        if (mode === 'advanced') {
            const maxSpeed = parseFloat(this.maxSpeedControl.value);
            if (diff < 500) {
                target = Math.min(maxSpeed, 1.25);
            } else if (diff > 1000) {
                target = 1.2;
            } else {
                target = this.userConfiguredSpeed;
            }
        }

        // Aplicação com suavização
        const ease = 0.25;
        this.speedControl.value = this.speedControl.value + (target - this.speedControl.value) * ease;
        if (this.speakingControlMode === 'slowDown') {
            this.video.playbackRate = 1.0 + (target < 1.0 ? (target - 1.0) / ease : 0);
        }

        metrics.record({ diff, mode, target });
        const health = metrics.getHealthSummary();
        console.info('[Sync]', JSON.stringify(health));

        this.updateRangeValue('speed');
    }
}
