## ✅ Versão 10 — Modo "Inteligente Híbrido": Automático + Intervenção do Usuário

Combinou tudo: histerese, suavização, contexto, previsão e permissão de intervenção manual.

```javascript
const SYNC_STATE = { idling: false, drifting: false, synced: true };

adjustSynchronization(currentTime) {
    if (this.speechQueue.length === 0) {
        SYNC_STATE.idling = true;
        this.speedControl.value = 1.0;
        this.video.playbackRate = 1.0;
        return;
    }

    const nextSpeechTime = this.speechQueue[0].startTime;
    const diff = nextSpeechTime - currentTime;

    // Estado atual da sincronização
    const prevState = SYNC_STATE.synced;
    const isDrifting = !prevState && Math.abs(diff - 1000) > 500;

    if (this.dubbingMode === 'advanced') {
        // 1) Previsão baseada em ritmo médio
        const predictedDiff = this.predictedDiff || (diff > 200 ? diff : 1000);

        // 2) Decisão híbrida
        if (isDrifting) {
            // Força correção imediata
            const maxSpeed = parseFloat(this.maxSpeedControl.value);
            this.speedControl.value = Math.min(maxSpeed, 1.25);
            if (this.speakingControlMode === 'slowDown') {
                this.video.playbackRate = Math.min(this.video.playbackRate + 0.12, 1.2);
            }
            SYNC_STATE.drifting = true;
        } else if (diff < 500) {
            // Leve atraso → aceleração conservadora
            const cur = this.speedControl.value || 1.0;
            this.speedControl.value = Math.min(cur + 0.03, maxSpeed || 1.5);
            if (this.speakingControlMode === 'slowDown') {
                this.video.playbackRate = Math.min(cur + 0.06, 1.2);
            }
        } else if (diff > 1000) {
            // Adiantado → desacelera
            this.speedControl.value = Math.max(1.0, cur - 0.08);
            if (this.speakingControlMode === 'slowDown') {
                this.video.playbackRate = Math.max(this.video.playbackRate - 0.1, 0.95);
            }
        } else {
            // Sincronizado → recalibra
            this.speedControl.value = this.userConfiguredSpeed;
            if (this.speakingControlMode === 'slowDown') this.video.playbackRate = 1.0;
            SYNC_STATE.synced = true;
        }

        // Suavização final
        const ease = 0.2;
        this.speedControl.value = this.speedControl.value + (this.speedControl.value - this.speedControl.value) * ease; // placeholder
        // (na prática: applyEase(this.speedControl.value, target, ease))

        this.updateRangeValue('speed');
    }
}

// Helper opcional de easing
applyEase(current, target, factor) {
    return current + (target - current) * factor;
}
